/**
 * @description Reusable data access for Integration Hub. Every query and every insert, update, upsert, delete and
 * platform event publish in the framework goes through this class and runs in system mode. Who can see what is
 * controlled by the object sharing (Private) and the two permission sets, not by the running user's access.
 * Queries take bind variables only: callers never concatenate values into the SOQL text.
 * @group Integration Hub
 */
public with sharing class IntegrationHubData {

    /**
     * @description Result of a partial-success DML call: one entry per input record, in the same order.
     */
    public class Outcome {
        /** @description Error text per input index; indexes that succeeded are absent. */
        public Map<Integer, String> errorByIndex = new Map<Integer, String>();
        /** @description All error texts, in input order. */
        public List<String> errors = new List<String>();

        /**
         * @description True when every record was saved.
         * @return whether there were no errors
         */
        public Boolean isSuccess() {
            return errors.isEmpty();
        }

        /**
         * @description Error text of one input record.
         * @param index position of the record in the list that was saved
         * @return the error text, or null when that record was saved
         */
        public String errorAt(Integer index) {
            return errorByIndex.get(index);
        }
    }

    /* ------------------------------------------------------------------ queries */

    /**
     * @description Runs a query with bind variables in system mode.
     * @param soql the query text; values are referenced as :name and passed in binds
     * @param binds bind variable values by name (may be null)
     * @return the rows found
     */
    public static List<SObject> query(String soql, Map<String, Object> binds) {
        return new SystemMode().runQuery(soql, binds);
    }

    /**
     * @description Runs a query and returns the first row.
     * @param soql the query text
     * @param binds bind variable values by name (may be null)
     * @return the first row, or null when nothing matches
     */
    public static SObject queryFirst(String soql, Map<String, Object> binds) {
        List<SObject> rows = query(soql, binds);
        return rows.isEmpty() ? null : rows[0];
    }

    /**
     * @description Runs a SELECT COUNT() query in system mode.
     * @param soql the count query text
     * @param binds bind variable values by name (may be null)
     * @return the number of matching rows
     */
    public static Integer countQuery(String soql, Map<String, Object> binds) {
        return new SystemMode().runCountQuery(soql, binds);
    }

    /**
     * @description Query locator for batch Apex, in system mode.
     * @param soql the query text
     * @param binds bind variable values by name (may be null)
     * @return the query locator
     */
    public static Database.QueryLocator locator(String soql, Map<String, Object> binds) {
        return new SystemMode().runLocator(soql, binds);
    }

    /* ------------------------------------------------------------------ all-or-none DML (throws DmlException) */

    /**
     * @description Inserts the records in system mode; any failure rolls back the call and throws.
     * @param records the records to insert
     */
    public static void insertAll(List<SObject> records) {
        if (hasRows(records)) {
            new SystemMode().runInsertAll(records);
        }
    }

    /**
     * @description Updates the records in system mode; any failure rolls back the call and throws.
     * @param records the records to update
     */
    public static void updateAll(List<SObject> records) {
        if (hasRows(records)) {
            new SystemMode().runUpdateAll(records);
        }
    }

    /**
     * @description Upserts the records in system mode, matching on Id; any failure throws.
     * @param records the records to upsert (one SObject type; any list type is accepted)
     */
    public static void upsertAll(List<SObject> records) {
        if (hasRows(records)) {
            new SystemMode().runUpsertAll(records, null);
        }
    }

    /**
     * @description Upserts the records in system mode, matching on an external Id field; any failure throws.
     * @param records the records to upsert (one SObject type; any list type is accepted)
     * @param matchField the external Id field to match on
     */
    public static void upsertAll(List<SObject> records, Schema.SObjectField matchField) {
        if (hasRows(records)) {
            new SystemMode().runUpsertAll(records, matchField);
        }
    }

    /**
     * @description Deletes the records in system mode; any failure throws.
     * @param records the records to delete
     */
    public static void deleteAll(List<SObject> records) {
        if (hasRows(records)) {
            new SystemMode().runDeleteAll(records);
        }
    }

    /* ------------------------------------------------------------------ partial-success DML */

    /**
     * @description Inserts the records in system mode; records that fail are reported, the rest are saved.
     * @param records the records to insert
     * @return the outcome, one entry per record
     */
    public static Outcome insertEach(List<SObject> records) {
        return hasRows(records) ? new SystemMode().runInsertEach(records) : new Outcome();
    }

    /**
     * @description Updates the records in system mode; records that fail are reported, the rest are saved.
     * @param records the records to update
     * @return the outcome, one entry per record
     */
    public static Outcome updateEach(List<SObject> records) {
        return hasRows(records) ? new SystemMode().runUpdateEach(records) : new Outcome();
    }

    /**
     * @description Deletes the records in system mode; records that fail are reported, the rest are deleted.
     * @param records the records to delete
     * @return the outcome, one entry per record
     */
    public static Outcome deleteEach(List<SObject> records) {
        return hasRows(records) ? new SystemMode().runDeleteEach(records) : new Outcome();
    }

    /**
     * @description Publishes platform events; events that fail are reported.
     * @param events the platform event messages
     * @return the outcome, one entry per event
     */
    public static Outcome publish(List<SObject> events) {
        Outcome result = new Outcome();
        if (!hasRows(events)) {
            return result;
        }
        List<Database.SaveResult> saved = EventBus.publish(events);
        for (Integer i = 0; i < saved.size(); i++) {
            if (!saved[i].isSuccess()) {
                addErrors(result, i, saved[i].getErrors());
            }
        }
        return result;
    }

    /* ------------------------------------------------------------------ helpers */

    private static Boolean hasRows(List<SObject> records) {
        return records != null && !records.isEmpty();
    }

    private static void addErrors(Outcome result, Integer index, List<Database.Error> errors) {
        List<String> messages = new List<String>();
        for (Database.Error err : errors) {
            messages.add(err.getMessage());
        }
        String text = String.join(messages, '; ');
        result.errorByIndex.put(index, text);
        result.errors.add(text);
    }

    /**
     * @description Runs the database calls in system mode, without sharing, so the framework can read and write
     * its own records whatever the running user's access. Only this class touches the database.
     */
    private without sharing class SystemMode {

        List<SObject> runQuery(String soql, Map<String, Object> binds) {
            return Database.queryWithBinds(soql, binds == null ? new Map<String, Object>() : binds, AccessLevel.SYSTEM_MODE);
        }

        Integer runCountQuery(String soql, Map<String, Object> binds) {
            return Database.countQueryWithBinds(soql, binds == null ? new Map<String, Object>() : binds, AccessLevel.SYSTEM_MODE);
        }

        Database.QueryLocator runLocator(String soql, Map<String, Object> binds) {
            return Database.getQueryLocatorWithBinds(soql, binds == null ? new Map<String, Object>() : binds, AccessLevel.SYSTEM_MODE);
        }

        void runInsertAll(List<SObject> records) {
            Database.insert(records, true, AccessLevel.SYSTEM_MODE);
        }

        void runUpdateAll(List<SObject> records) {
            Database.update(records, true, AccessLevel.SYSTEM_MODE);
        }

        void runUpsertAll(List<SObject> records, Schema.SObjectField matchField) {
            List<SObject> typed = concreteList(records);
            if (matchField == null) {
                Database.upsert(typed, true, AccessLevel.SYSTEM_MODE);
            } else {
                Database.upsert(typed, matchField, true, AccessLevel.SYSTEM_MODE);
            }
        }

        /* Upsert is not allowed on a generic List<SObject>: copy into a list of the concrete type. The same record
           instances are added, so the Ids set by the upsert are visible to the caller. */
        List<SObject> concreteList(List<SObject> records) {
            String typeName = records[0].getSObjectType().getDescribe(SObjectDescribeOptions.DEFERRED).getName();
            List<SObject> typed = (List<SObject>) Type.forName('List<' + typeName + '>').newInstance();
            typed.addAll(records);
            return typed;
        }

        void runDeleteAll(List<SObject> records) {
            Database.delete(records, true, AccessLevel.SYSTEM_MODE);
        }

        Outcome runInsertEach(List<SObject> records) {
            Outcome result = new Outcome();
            List<Database.SaveResult> saved = Database.insert(records, false, AccessLevel.SYSTEM_MODE);
            for (Integer i = 0; i < saved.size(); i++) {
                if (!saved[i].isSuccess()) {
                    addErrors(result, i, saved[i].getErrors());
                }
            }
            return result;
        }

        Outcome runUpdateEach(List<SObject> records) {
            Outcome result = new Outcome();
            List<Database.SaveResult> saved = Database.update(records, false, AccessLevel.SYSTEM_MODE);
            for (Integer i = 0; i < saved.size(); i++) {
                if (!saved[i].isSuccess()) {
                    addErrors(result, i, saved[i].getErrors());
                }
            }
            return result;
        }

        Outcome runDeleteEach(List<SObject> records) {
            Outcome result = new Outcome();
            List<Database.DeleteResult> deleted = Database.delete(records, false, AccessLevel.SYSTEM_MODE);
            for (Integer i = 0; i < deleted.size(); i++) {
                if (!deleted[i].isSuccess()) {
                    addErrors(result, i, deleted[i].getErrors());
                }
            }
            return result;
        }
    }
}
